import{_ as a,o as t,a as o,a2 as n}from"./chunks/framework.DCcmcJcL.js";const u=JSON.parse('{"title":"Common Pitfalls","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/common-pitfalls.md","filePath":"advanced/common-pitfalls.md","lastUpdated":1789464754000}'),s={name:"advanced/common-pitfalls.md"};function i(r,e,l,d,c,h){return t(),o("div",null,e[0]||(e[0]=[n('<h1 id="common-pitfalls" tabindex="-1">Common Pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common Pitfalls&quot;">​</a></h1><p>The problems Bagisto developers run into again and again, each as the symptom, its cause in the code, and the fix. To investigate something that isn&#39;t listed here, start with <a href="./debugging.html">Debugging Tips</a>.</p><h2 id="installation-and-setup" tabindex="-1">Installation and Setup <a class="header-anchor" href="#installation-and-setup" aria-label="Permalink to &quot;Installation and Setup&quot;">​</a></h2><h3 id="php-version-and-extensions" tabindex="-1">PHP Version and Extensions <a class="header-anchor" href="#php-version-and-extensions" aria-label="Permalink to &quot;PHP Version and Extensions&quot;">​</a></h3><ul><li><strong>Symptom:</strong> <code>composer install</code> fails with a platform error, or every request stops with a PHP version error.</li><li><strong>Cause:</strong> Bagisto 2.5 requires PHP 8.4 (<code>&quot;php&quot;: &quot;^8.4&quot;</code> in <code>composer.json</code>; the locked dependencies need 8.4.1 or later), while 2.4 accepts 8.3 or 8.4. A second, older PHP binary often comes first on the <code>PATH</code>. <code>composer.json</code> also requires the <code>calendar</code>, <code>curl</code>, <code>intl</code>, <code>mbstring</code>, <code>openssl</code>, <code>pdo</code>, <code>pdo_mysql</code> and <code>tokenizer</code> extensions, and a PostgreSQL store needs <code>pdo_pgsql</code>.</li><li><strong>Fix:</strong> Check the PHP that Composer runs with <code>php -v</code> and <code>composer check-platform-reqs</code>, which lists anything missing.</li></ul><h3 id="storage-link-and-app-url" tabindex="-1">Storage Link and <code>APP_URL</code> <a class="header-anchor" href="#storage-link-and-app-url" aria-label="Permalink to &quot;Storage Link and `APP_URL`&quot;">​</a></h3><ul><li><strong>Symptom:</strong> Channel logos, category images or theme section images under <code>/storage</code> are broken; or, often after the store moves to another domain, only channel logos and category images point at the wrong host.</li><li><strong>Cause:</strong> Every file served from <code>/storage</code> needs the <code>public/storage</code> link to <code>storage/app/public</code>. Channel logos and category images are also built with <code>Storage::url()</code>, which takes its host from <code>APP_URL</code> (the <code>public</code> disk&#39;s <code>url</code> in <code>config/filesystems.php</code>), so it must match the URL you browse, port included. Theme section images and resized images under <code>/cache/…</code> use the request&#39;s own host.</li><li><strong>Fix:</strong> Run <code>php artisan storage:link</code> and correct <code>APP_URL</code>; <code>php artisan about</code> shows the URL and whether the link exists.</li></ul><h3 id="running-bagisto-install-on-an-existing-store" tabindex="-1">Running <code>bagisto:install</code> on an Existing Store <a class="header-anchor" href="#running-bagisto-install-on-an-existing-store" aria-label="Permalink to &quot;Running `bagisto:install` on an Existing Store&quot;">​</a></h3><ul><li><strong>Symptom:</strong> Every order, customer and product is gone.</li><li><strong>Cause:</strong> <code>php artisan bagisto:install</code> sets up a new store: it generates a new <code>APP_KEY</code> and runs <code>db:wipe</code> and <code>migrate:fresh</code> before seeding.</li><li><strong>Fix:</strong> Upgrade with <code>php artisan migrate</code>, never <code>bagisto:install</code>. See <a href="./../getting-started/upgrade-guide.html">Upgrade Guide</a>.</li></ul><h3 id="migrate-fresh-without-seeding" tabindex="-1"><code>migrate:fresh</code> Without Seeding <a class="header-anchor" href="#migrate-fresh-without-seeding" aria-label="Permalink to &quot;`migrate:fresh` Without Seeding&quot;">​</a></h3><ul><li><strong>Symptom:</strong> The storefront and the admin stop working after <code>php artisan migrate:fresh</code>.</li><li><strong>Cause:</strong> The tables are empty: no channel, locale, currency, customer group or admin, which the storefront and the admin read on every request.</li><li><strong>Fix:</strong> Run <code>php artisan db:seed</code>; the application&#39;s <code>DatabaseSeeder</code> runs the installer&#39;s seeders.</li></ul><h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><h3 id="code-that-only-ever-ran-on-mysql" tabindex="-1">Code That Only Ever Ran on MySQL <a class="header-anchor" href="#code-that-only-ever-ran-on-mysql" aria-label="Permalink to &quot;Code That Only Ever Ran on MySQL&quot;">​</a></h3><ul><li><strong>Symptom:</strong> A package that works on MySQL fails on PostgreSQL with type, grouping or syntax errors, or searches that no longer match.</li><li><strong>Cause:</strong> Bagisto runs on MySQL 8.0, MariaDB 10.11 and PostgreSQL 16 (2.4 has no PostgreSQL support). PostgreSQL has a case-sensitive <code>LIKE</code>, truncates <code>CAST(… AS CHAR)</code> to one character, rejects ungrouped selected columns and empty strings in typed columns, and returns booleans as <code>true</code> and <code>false</code>.</li><li><strong>Fix:</strong> Route database-specific SQL through <code>db_grammar()</code> and cast boolean columns; see <a href="./database-compatibility.html">Database Compatibility</a>.</li></ul><h3 id="migration-order" tabindex="-1">Migration Order <a class="header-anchor" href="#migration-order" aria-label="Permalink to &quot;Migration Order&quot;">​</a></h3><ul><li><strong>Symptom:</strong> A migration in your package fails to add a foreign key to a core table.</li><li><strong>Cause:</strong> Laravel sorts the migrations of every package into one list by file name, whichever service provider loaded them.</li><li><strong>Fix:</strong> Give the migration a timestamp later than the core migration that creates the table.</li></ul><h3 id="switching-file-storage" tabindex="-1">Switching File Storage <a class="header-anchor" href="#switching-file-storage" aria-label="Permalink to &quot;Switching File Storage&quot;">​</a></h3><ul><li><strong>Symptom:</strong> After choosing Amazon S3 or Cloudflare R2 in the admin&#39;s File Management configuration, existing product and category images are missing.</li><li><strong>Cause:</strong> New uploads go to the new disk, and the storefront looks for existing files there too, but nothing copies them.</li><li><strong>Fix:</strong> Copy <code>storage/app/public</code> to the bucket before switching; see <a href="./file-storage.html">File Storage</a>.</li></ul><h2 id="package-development" tabindex="-1">Package Development <a class="header-anchor" href="#package-development" aria-label="Permalink to &quot;Package Development&quot;">​</a></h2><h3 id="editing-core-packages" tabindex="-1">Editing Core Packages <a class="header-anchor" href="#editing-core-packages" aria-label="Permalink to &quot;Editing Core Packages&quot;">​</a></h3><ul><li><strong>Symptom:</strong> Your change disappears or conflicts on the next Bagisto update.</li><li><strong>Cause:</strong> It was made inside <code>packages/Webkul/&lt;Package&gt;</code> or <code>vendor/</code>.</li><li><strong>Fix:</strong> Put it in your own package: override the view from a theme, listen to the event, merge configuration from your service provider, or replace the model through Concord. See <a href="./event-listeners.html">Event Listeners</a> and <a href="./../package-development/models.html">Models</a>.</li></ul><h3 id="registering-a-package" tabindex="-1">Registering a Package <a class="header-anchor" href="#registering-a-package" aria-label="Permalink to &quot;Registering a Package&quot;">​</a></h3><ul><li><strong>Symptom:</strong> The package&#39;s classes aren&#39;t found, or its routes, views, translations, migrations or models never load.</li><li><strong>Cause:</strong> One of its three registrations is missing: the namespace in <code>autoload</code> in the root <code>composer.json</code> (classes), the service provider in <code>bootstrap/providers.php</code> (routes, views, translations, migrations), or, for a package with models, the <code>ModuleServiceProvider</code> in <code>config/concord.php</code> (models).</li><li><strong>Fix:</strong> Add the missing one, and run <code>composer dump-autoload</code> after editing <code>composer.json</code>. See <a href="./../package-development/getting-started.html">Package Development</a> and <a href="./../package-development/models.html#the-manifest-file">Models</a>.</li></ul><h3 id="admin-routes-need-an-acl-entry" tabindex="-1">Admin Routes Need an ACL Entry <a class="header-anchor" href="#admin-routes-need-an-acl-entry" aria-label="Permalink to &quot;Admin Routes Need an ACL Entry&quot;">​</a></h3><ul><li><strong>Symptom:</strong> A restricted admin role gets <code>401</code> on your route, while the default administrator can open it.</li><li><strong>Cause:</strong> The <code>admin</code> middleware, <code>Webkul\\User\\Http\\Middleware\\Bouncer</code>, refuses any admin route that isn&#39;t mapped in an <code>acl.php</code> and isn&#39;t in its short list of routes every admin may use. It applies to every role whose permission type isn&#39;t <strong>All</strong>, so testing as the default administrator hides the problem.</li><li><strong>Fix:</strong> Add an ACL entry for every admin route, and use the same key with <code>bouncer()-&gt;hasPermission()</code> in controllers and views; see <a href="./../package-development/access-control-list.html">Access Control List</a>.</li></ul><h3 id="saving-a-product-outside-the-admin-controller" tabindex="-1">Saving a Product Outside the Admin Controller <a class="header-anchor" href="#saving-a-product-outside-the-admin-controller" aria-label="Permalink to &quot;Saving a Product Outside the Admin Controller&quot;">​</a></h3><ul><li><p><strong>Symptom:</strong> A product written from your own code keeps its old price, stock or page on the storefront.</p></li><li><p><strong>Cause:</strong> The admin&#39;s <code>ProductController</code> dispatches <code>catalog.product.update.before</code> and <code>catalog.product.update.after</code> around its save, and the listeners on the <code>after</code> event refresh the flat row, queue the indexing, reindex catalog rule prices, record the Omnibus price and clear the page and catalog API caches. Eloquent, the query builder and even <code>ProductRepository::update()</code> skip all of that.</p></li><li><p><strong>Fix:</strong> Fire the same pair around your write:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Event</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dispatch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;catalog.product.update.before&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, $id);</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$product </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> $this</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">productRepository</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($data, $id);</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Event</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dispatch</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;catalog.product.update.after&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, $product);</span></span></code></pre></div><p><code>php artisan event:list --event=catalog.product.update.after</code> lists the listeners.</p></li></ul><h2 id="front-end-and-assets" tabindex="-1">Front End and Assets <a class="header-anchor" href="#front-end-and-assets" aria-label="Permalink to &quot;Front End and Assets&quot;">​</a></h2><h3 id="assets-not-rebuilt" tabindex="-1">Assets Not Rebuilt <a class="header-anchor" href="#assets-not-rebuilt" aria-label="Permalink to &quot;Assets Not Rebuilt&quot;">​</a></h3><ul><li><strong>Symptom:</strong> A CSS, JavaScript or Vue change doesn&#39;t show in the browser.</li><li><strong>Cause:</strong> Admin, Shop and Installer each have their own <code>vite.config.js</code> and npm scripts; the Admin and Shop builds are written to <code>public/themes/admin/default/build</code> and <code>public/themes/shop/default/build</code>.</li><li><strong>Fix:</strong> Run <code>npm run build</code> from that package&#39;s directory, such as <code>packages/Webkul/Shop</code>, or <code>npm run dev</code> to serve the assets from Vite&#39;s development server while you work.</li></ul><h3 id="missing-tailwind-classes" tabindex="-1">Missing Tailwind Classes <a class="header-anchor" href="#missing-tailwind-classes" aria-label="Permalink to &quot;Missing Tailwind Classes&quot;">​</a></h3><ul><li><strong>Symptom:</strong> A Tailwind class, or an icon, renders with no style.</li><li><strong>Cause:</strong> Tailwind generates only the classes it finds in the files it scans. The <code>source(&quot;../../../&quot;)</code> argument at the top of the Admin and Shop <code>app.css</code> covers that package&#39;s <code>src/</code> directory, so a class used only in a theme under <code>resources/themes</code> or another package isn&#39;t generated, and neither is a class name built at runtime. Icon classes are declared in <code>app.css</code> too.</li><li><strong>Fix:</strong> Add an <code>@source</code> line for the extra path, or an <code>@source inline(...)</code> entry for runtime class names, then rebuild. On 2.4 (Tailwind 3) use the <code>content</code> array and <code>safelist</code> in the package&#39;s <code>tailwind.config.js</code>.</li></ul><h2 id="caching" tabindex="-1">Caching <a class="header-anchor" href="#caching" aria-label="Permalink to &quot;Caching&quot;">​</a></h2><h3 id="stale-configuration-after-env-changes" tabindex="-1">Stale Configuration After <code>.env</code> Changes <a class="header-anchor" href="#stale-configuration-after-env-changes" aria-label="Permalink to &quot;Stale Configuration After `.env` Changes&quot;">​</a></h3><ul><li><strong>Symptom:</strong> An edit to <code>.env</code> or <code>config/</code> has no effect.</li><li><strong>Cause:</strong> <code>php artisan config:cache</code> has been run, and the cached configuration wins over <code>.env</code> until it&#39;s cleared.</li><li><strong>Fix:</strong> Run <code>php artisan optimize:clear</code>.</li></ul><h3 id="full-page-cache-serving-old-pages" tabindex="-1">Full Page Cache Serving Old Pages <a class="header-anchor" href="#full-page-cache-serving-old-pages" aria-label="Permalink to &quot;Full Page Cache Serving Old Pages&quot;">​</a></h3><ul><li><strong>Symptom:</strong> A guest sees an old storefront page that a signed-in customer doesn&#39;t.</li><li><strong>Cause:</strong> The change fired no event the full page cache listens for, such as an import or a direct database write. Signed-in customers are never served cached pages (<code>packages/Webkul/FPC/src/CacheProfiles/FullPageCacheProfile.php</code>), so the problem only reproduces as a guest.</li><li><strong>Fix:</strong> Run <code>php artisan responsecache:clear</code>. <code>--url</code> forgets only one channel, locale and currency variant; see <a href="./../performance/configure-fpc.html#clear-the-cache">Configure Full Page Cache</a>.</li></ul><h2 id="queues" tabindex="-1">Queues <a class="header-anchor" href="#queues" aria-label="Permalink to &quot;Queues&quot;">​</a></h2><h3 id="the-sync-queue-in-production" tabindex="-1">The Sync Queue in Production <a class="header-anchor" href="#the-sync-queue-in-production" aria-label="Permalink to &quot;The Sync Queue in Production&quot;">​</a></h3><ul><li><strong>Symptom:</strong> Product saves are slow, and mail and indexing hold up the admin&#39;s requests.</li><li><strong>Cause:</strong> <code>.env.example</code> sets <code>QUEUE_CONNECTION=sync</code>, which runs every job inside the request, so a product save runs its inventory, price and search indexing before the page returns.</li><li><strong>Fix:</strong> Set <code>QUEUE_CONNECTION</code> to <code>database</code> or <code>redis</code> and run a worker on both queues core uses, <code>php artisan queue:work --queue=default,broadcastable</code>. See <a href="./queue-jobs-scheduling.html#running-workers-in-production">Queues, Jobs and Scheduling</a>.</li></ul><h2 id="mail" tabindex="-1">Mail <a class="header-anchor" href="#mail" aria-label="Permalink to &quot;Mail&quot;">​</a></h2><h3 id="smtp-settings-from-the-admin-are-ignored" tabindex="-1">SMTP Settings from the Admin Are Ignored <a class="header-anchor" href="#smtp-settings-from-the-admin-are-ignored" aria-label="Permalink to &quot;SMTP Settings from the Admin Are Ignored&quot;">​</a></h3><ul><li><strong>Symptom:</strong> Mail doesn&#39;t use the SMTP host and credentials saved in the admin&#39;s email configuration.</li><li><strong>Cause:</strong> Those settings (<code>emails.configure.smtp.*</code>) are read only by the <code>bagisto-dynamic-smtp</code> mailer that <code>Webkul\\Core\\Providers\\DynamicMailServiceProvider</code> registers, which falls back to <code>config(&#39;mail.mailers.smtp&#39;)</code> for any empty setting. <code>MAIL_MAILER</code> in <code>.env</code> naming another mailer bypasses it, and the admin&#39;s configuration screen shows a notice saying so.</li><li><strong>Fix:</strong> Set <code>MAIL_MAILER=bagisto-dynamic-smtp</code>, as <code>.env.example</code> does.</li></ul><h2 id="admin-and-debugging" tabindex="-1">Admin and Debugging <a class="header-anchor" href="#admin-and-debugging" aria-label="Permalink to &quot;Admin and Debugging&quot;">​</a></h2><h3 id="changing-the-admin-url" tabindex="-1">Changing the Admin URL <a class="header-anchor" href="#changing-the-admin-url" aria-label="Permalink to &quot;Changing the Admin URL&quot;">​</a></h3><ul><li><strong>Symptom:</strong> The admin still answers on the old prefix, or returns <code>404</code> on the new one.</li><li><strong>Cause:</strong> <code>APP_ADMIN_URL</code> sets the prefix of every admin route (<code>config(&#39;app.admin_url&#39;)</code>, <code>admin</code> by default), and the configuration and routes are cached.</li><li><strong>Fix:</strong> Run <code>php artisan optimize:clear</code> after changing it. The storefront maintenance page never applies under that prefix.</li></ul><h3 id="setting-app-debug-allowed-ips" tabindex="-1">Setting <code>APP_DEBUG_ALLOWED_IPS</code> <a class="header-anchor" href="#setting-app-debug-allowed-ips" aria-label="Permalink to &quot;Setting `APP_DEBUG_ALLOWED_IPS`&quot;">​</a></h3><ul><li><strong>Symptom:</strong> Every request and artisan command stops with a class-not-found error for the old Debugbar facade.</li><li><strong>Cause:</strong> Any value in <code>APP_DEBUG_ALLOWED_IPS</code> makes <code>AppServiceProvider</code> call a facade that the installed debug bar no longer ships.</li><li><strong>Fix:</strong> Leave it empty and control the debug bar with <code>APP_DEBUG</code> and <code>DEBUGBAR_ENABLED</code>; see <a href="./debugging.html#when-it-appears">Debugging Tips</a>.</li></ul><h2 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h2><h3 id="search-index-out-of-date" tabindex="-1">Search Index Out of Date <a class="header-anchor" href="#search-index-out-of-date" aria-label="Permalink to &quot;Search Index Out of Date&quot;">​</a></h3><ul><li><strong>Symptom:</strong> Elasticsearch results, price sorting or filters don&#39;t match the catalog after attribute, category or customer group changes, or after the nightly price reindex.</li><li><strong>Cause:</strong> A document holds the product as it was last indexed. Attribute, category and customer group changes and the scheduled price reindexes don&#39;t rewrite it; see <a href="./search-engines.html#things-to-watch">Search Engines</a>.</li><li><strong>Fix:</strong> Run <code>php artisan indexer:index --type=search --mode=full</code> (<code>--type=elastic</code> on 2.4); it does nothing unless an external search engine is enabled. For connection problems, see <a href="./../performance/configure-elasticsearch.html#troubleshooting">Configure Elasticsearch</a>.</li></ul><h2 id="channels-and-locales" tabindex="-1">Channels and Locales <a class="header-anchor" href="#channels-and-locales" aria-label="Permalink to &quot;Channels and Locales&quot;">​</a></h2><h3 id="settings-are-per-channel-and-locale" tabindex="-1">Settings Are per Channel and Locale <a class="header-anchor" href="#settings-are-per-channel-and-locale" aria-label="Permalink to &quot;Settings Are per Channel and Locale&quot;">​</a></h3><ul><li><strong>Symptom:</strong> A setting saved in the admin reads as its default in code, or on another channel.</li><li><strong>Cause:</strong> Many settings are saved per channel, per locale, or both, and <code>core()-&gt;getConfigData()</code> reads the current channel and locale, falling back to the field&#39;s default when nothing is saved there.</li><li><strong>Fix:</strong> Save the setting for the channel and locale that reads it, or pass the channel and locale codes to <code>core()-&gt;getConfigData()</code>.</li></ul><h3 id="maintenance-mode-is-one-switch-plus-a-flag-per-channel" tabindex="-1">Maintenance Mode Is One Switch Plus a Flag per Channel <a class="header-anchor" href="#maintenance-mode-is-one-switch-plus-a-flag-per-channel" aria-label="Permalink to &quot;Maintenance Mode Is One Switch Plus a Flag per Channel&quot;">​</a></h3><ul><li><strong>Symptom:</strong> A channel&#39;s maintenance page doesn&#39;t appear, or saving one channel brings every channel back up.</li><li><strong>Cause:</strong> The storefront shows its maintenance page only when Laravel&#39;s maintenance mode is on <strong>and</strong> the current channel&#39;s <code>is_maintenance_on</code> is set (<code>Webkul\\Core\\Http\\Middleware\\PreventRequestsDuringMaintenance</code>); the admin URL and the channel&#39;s allowed IPs always get through. <code>php artisan down</code> sets the flag on every channel and turns maintenance mode on; <code>php artisan up</code> clears both. Saving a channel turns maintenance mode on or off to match that channel alone, so saving one with maintenance off brings back every channel.</li><li><strong>Fix:</strong> After changing maintenance on one channel, check the others and confirm the state with <code>php artisan about</code>. On more than one web server, share the state with <code>APP_MAINTENANCE_DRIVER=cache</code>; see <a href="./../performance/configure-load-balancing.html">Configure Load Balancing</a>.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><h3 id="tests-see-your-store-s-data" tabindex="-1">Tests See Your Store&#39;s Data <a class="header-anchor" href="#tests-see-your-store-s-data" aria-label="Permalink to &quot;Tests See Your Store&#39;s Data&quot;">​</a></h3><ul><li><strong>Symptom:</strong> A test that counts rows or reads the first row of a listing fails, or a test fails with &quot;table not found&quot;.</li><li><strong>Cause:</strong> The Pest suite runs against the database in <code>.env</code>, inside a transaction per test, and a normal run never migrates.</li><li><strong>Fix:</strong> Assert on the records the test created, and run <code>php artisan migrate</code> first when your package adds a table; see <a href="./testing-with-pest.html#the-test-database">Testing with Pest</a>.</li></ul><h3 id="stale-parallel-test-databases" tabindex="-1">Stale Parallel Test Databases <a class="header-anchor" href="#stale-parallel-test-databases" aria-label="Permalink to &quot;Stale Parallel Test Databases&quot;">​</a></h3><ul><li><strong>Symptom:</strong> <code>vendor/bin/pest --parallel</code> fails after a seeder or an existing migration changed, although the code is right.</li><li><strong>Cause:</strong> The <code>_test_N</code> databases are kept between runs and only migrated forward.</li><li><strong>Fix:</strong> Run <code>vendor/bin/pest --parallel --recreate-databases</code>.</li></ul><h3 id="the-translations-check-fails-for-a-new-package" tabindex="-1">The Translations Check Fails for a New Package <a class="header-anchor" href="#the-translations-check-fails-for-a-new-package" aria-label="Permalink to &quot;The Translations Check Fails for a New Package&quot;">​</a></h3><ul><li><strong>Symptom:</strong> <code>php artisan bagisto:translations:check</code> reports missing locale folders for your package, or never checks it.</li><li><strong>Cause:</strong> It expects every supported locale folder in each package directly under <code>packages/Webkul</code>, and ignores packages anywhere else.</li><li><strong>Fix:</strong> Add every locale folder; see <a href="./coding-standards.html#translations">Coding Standards</a>.</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./debugging.html">Debugging Tips</a>: the tools for a problem that isn&#39;t listed here.</li><li><a href="./database-compatibility.html">Database Compatibility</a>: writing SQL that runs on MySQL, MariaDB and PostgreSQL.</li><li><a href="./../performance/configure-fpc.html">Configure Full Page Cache</a>: the page cache&#39;s store, checks and clearing.</li></ul>',65)]))}const p=a(s,[["render",i]]);export{u as __pageData,p as default};
